Writing PostgreSQL migration. Idempotent via `IF NOT EXISTS` and checks before backfill.

```sql
-- Migration: Split users.full_name → first_name, last_name
-- Safe: re-runnable, preserves data, reverses cleanly

BEGIN;

-- Add columns if missing
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                 WHERE table_name='users' AND column_name='first_name') THEN
    ALTER TABLE users ADD COLUMN first_name VARCHAR(255);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns 
                 WHERE table_name='users' AND column_name='last_name') THEN
    ALTER TABLE users ADD COLUMN last_name VARCHAR(255);
  END IF;
END $$;

-- Backfill: split full_name only if target columns empty
DO $$
DECLARE
  full_name_exists BOOLEAN;
BEGIN
  SELECT EXISTS(SELECT 1 FROM information_schema.columns 
                WHERE table_name='users' AND column_name='full_name')
  INTO full_name_exists;

  IF full_name_exists THEN
    UPDATE users 
    SET 
      first_name = TRIM(SUBSTRING_INDEX(full_name, ' ', 1)),
      last_name = TRIM(SUBSTRING_INDEX(full_name, ' ', -1))
    WHERE full_name IS NOT NULL 
      AND (first_name IS NULL OR last_name IS NULL);
  END IF;
END $$;

-- Handle single names (no space) → first_name only, last_name empty
UPDATE users 
SET last_name = ''
WHERE full_name IS NOT NULL 
  AND full_name NOT LIKE '% %'
  AND last_name IS NULL;

-- Add constraints (optional, after backfill stable)
-- ALTER TABLE users ALTER COLUMN first_name SET NOT NULL;
-- ALTER TABLE users ALTER COLUMN last_name SET NOT NULL;

COMMIT;
```

**For MySQL** (simpler syntax):
```sql
START TRANSACTION;

ALTER TABLE users 
  ADD COLUMN first_name VARCHAR(255) IF NOT EXISTS,
  ADD COLUMN last_name VARCHAR(255) IF NOT EXISTS;

UPDATE users 
SET 
  first_name = TRIM(SUBSTRING_INDEX(full_name, ' ', 1)),
  last_name = TRIM(IF(full_name LIKE '% %', SUBSTRING_INDEX(full_name, ' ', -1), ''))
WHERE full_name IS NOT NULL 
  AND (first_name IS NULL OR first_name = '');

COMMIT;
```

**Idempotent checks:**
- Columns checked via `information_schema` before add
- Backfill only runs if target columns empty
- Safe to run multiple times

**Reverse** (if needed):
```sql
BEGIN;
ALTER TABLE users DROP COLUMN first_name, DROP COLUMN last_name;
COMMIT;
```

